  // examples/card_examples.dart
  'card_pressable':
      'class CardPressableExample extends StatefulWidget {\n'
      '  const CardPressableExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<CardPressableExample> createState() => _CardPressableExampleState();\n'
      '}\n'
      '\n'
      'class _CardPressableExampleState extends State<CardPressableExample> {\n'
      '  String? _selected = \'pro\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A nullable `onPressed` is the whole difference between a card and\n'
      '    // upstream\'s second `ClickableCard`: set it and the card gains hover,\n'
      '    // press, a focus ring, `Semantics(button: true)` and a tap target.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 160,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final plan in const <List<String>>[\n'
      '          <String>[\'free\', \'Free\', \'One project\'],\n'
      '          <String>[\'pro\', \'Pro\', \'Unlimited projects\'],\n'
      '        ])\n'
      '          AstryxCard(\n'
      '            semanticsLabel: \'Choose the \${plan[1]} plan\',\n'
      '            variant: _selected == plan[0]\n'
      '                ? const AstryxCardVariant.palette(AstryxPalette.blue)\n'
      '                : AstryxCardVariant.standard,\n'
      '            onPressed: () => setState(() => _selected = plan[0]),\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing1,\n'
      '              children: <Widget>[\n'
      '                AstryxText(plan[1], type: AstryxTextType.large),\n'
      '                AstryxText(\n'
      '                  plan[2],\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
