      '        ),\n'
      '        AstryxDialog(\n'
      '          controller: _controller,\n'
      '          title: \'New project\',\n'
      '          width: 420,\n'
      '          footer: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.end,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(label: \'Cancel\', onPressed: _controller.hide),\n'
      '              AstryxButton(\n'
      '                label: \'Create\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                onPressed: _controller.hide,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxTextInput(\n'
      '                label: \'Name\',\n'
      '                controller: _name,\n'
      '                required: true,\n'
      '                autofocus: true,\n'
      '                placeholder: \'Atlas\',\n'
      '              ),\n'
      '              const AstryxSelector<String>(\n'
      '                label: \'Region\',\n'
      '                value: \'eu\',\n'
      '                options: <AstryxSelectorEntry<String>>[\n'
      '                  AstryxSelectorOption(value: \'eu\', label: \'Europe\'),\n'
      '                  AstryxSelectorOption(value: \'us\', label: \'United States\'),\n'
      '                ],\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
