  'stack_justify':
      'class StackJustifyExample extends StatelessWidget {\n'
      '  const StackJustifyExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `justify` only bites when the stack has room to distribute, which is why\n'
      '    // each row asks for `MainAxisSize.max`.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final justify in AstryxStackJustify.values)\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxText(justify.name, type: AstryxTextType.label),\n'
      '              AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                justify: justify,\n'
      '                mainAxisSize: MainAxisSize.max,\n'
