  // examples/tab_list_examples.dart
  'tab_list_demo':
      'class TabListDemoExample extends StatefulWidget {\n'
      '  const TabListDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TabListDemoExample> createState() => _TabListDemoExampleState();\n'
      '}\n'
      '\n'
      'class _TabListDemoExampleState extends State<TabListDemoExample> {\n'
      '  String _tab = \'overview\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The strip owns no panel. It reports a value; the application decides what\n'
      '    // that value shows — which is what keeps a tab bar usable with routing.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTabList<String>(\n'
      '          label: \'Project sections\',\n'
      '          value: _tab,\n'
      '          onChanged: (value) => setState(() => _tab = value),\n'
      '          tabs: const <AstryxTab<String>>[\n'
      '            AstryxTab(value: \'overview\', label: \'Overview\'),\n'
      '            AstryxTab(value: \'activity\', label: \'Activity\'),\n'
      '            AstryxTab(value: \'settings\', label: \'Settings\'),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(switch (_tab) {\n'
      '          \'overview\' => \'4,201 requests this month.\',\n'
      '          \'activity\' => \'Ada deployed 20 minutes ago.\',\n'
      '          _ => \'Two admins, twenty-two members.\',\n'
      '        }),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
