      '  const TableSortingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TableSortingExample> createState() => _TableSortingExampleState();\n'
      '}\n'
      '\n'
      'class _TableSortingExampleState extends State<TableSortingExample> {\n'
      '  AstryxTableSort? _sort = const AstryxTableSort(\n'
      '    \'name\',\n'
      '    AstryxSortDirection.ascending,\n'
      '  );\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A column is sortable when — and only when — it has a `compare`. Pressing\n'
      '    // a header cycles ascending → descending → unsorted, because without that\n'
      '    // third state a user cannot get back to the order the data arrived in.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTable<Project>(\n'
      '          label: \'Projects\',\n'
      '          rows: projects,\n'
      '          keyOf: (row) => row.id,\n'
      '          sort: _sort,\n'
      '          onSortChanged: (sort) => setState(() => _sort = sort),\n'
      '          columns: <AstryxTableColumn<Project>>[\n'
      '            AstryxTableColumn<Project>(\n'
      '              id: \'name\',\n'
      '              header: \'Project\',\n'
      '              compare: (a, b) => a.name.compareTo(b.name),\n'
      '              cellBuilder: (context, row) => AstryxText(row.name),\n'
      '            ),\n'
      '            AstryxTableColumn<Project>(\n'
      '              id: \'owner\',\n'
      '              header: \'Owner\',\n'
      '              compare: (a, b) => a.owner.compareTo(b.owner),\n'
      '              cellBuilder: (context, row) => AstryxText(row.owner),\n'
      '            ),\n'
      '            AstryxTableColumn<Project>(\n'
      '              id: \'requests\',\n'
      '              header: \'Requests\',\n'
      '              width: const AstryxTableColumnWidth.fixed(120),\n'
      '              alignment: AstryxTableAlignment.end,\n'
      '              compare: (a, b) => a.requests.compareTo(b.requests),\n'
      '              cellBuilder: (context, row) =>\n'
      '                  AstryxText(\'\${row.requests}\', tabularNumbers: true),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _sort == null\n'
      '              ? \'Unsorted — the order the rows arrived in\'\n'
      '              : \'Sorted by \${_sort!.columnId}, \${_sort!.direction.name}\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/table_examples.dart
  'table_selection':
      'class TableSelectionExample extends StatefulWidget {\n'
      '  const TableSelectionExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TableSelectionExample> createState() => _TableSelectionExampleState();\n'
      '}\n'
      '\n'
      'class _TableSelectionExampleState extends State<TableSelectionExample> {\n'
      '  Set<Object> _selected = <Object>{\'p2\'};\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The header checkbox governs the *visible* rows, and goes indeterminate\n'
      '    // when only some are selected. `rowLabelOf` is what names each row\'s\n'
      '    // checkbox — without it every one announces "Select row".\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTable<Project>(\n'
      '          label: \'Projects\',\n'
      '          rows: projects,\n'
      '          keyOf: (row) => row.id,\n'
      '          selectionMode: AstryxTableSelectionMode.multiple,\n'
      '          selected: _selected,\n'
      '          onSelectionChanged: (value) => setState(() => _selected = value),\n'
      '          rowLabelOf: (row) => row.name,\n'
      '          columns: <AstryxTableColumn<Project>>[\n'
      '            AstryxTableColumn<Project>(\n'
      '              id: \'name\',\n'
      '              header: \'Project\',\n'
      '              cellBuilder: (context, row) => AstryxText(row.name),\n'
      '            ),\n'
      '            AstryxTableColumn<Project>(\n'
      '              id: \'health\',\n'
      '              header: \'Health\',\n'
      '              width: const AstryxTableColumnWidth.intrinsic(min: 96),\n'
      '              cellBuilder: (context, row) =>\n'
      '                  AstryxBadge(row.health, variant: variantFor(row.health)),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          \'\${_selected.length} selected\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/table_examples.dart
  'table_row_actions':
      'class TableRowActionsExample extends StatelessWidget {\n'
      '  const TableRowActionsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Row actions are **always visible**, never hover-only: hover does not\n'
      '    // exist on touch, and an action nobody can reach is not an action.\n'
      '    return AstryxTable<Project>(\n'
      '      label: \'Projects\',\n'
      '      rows: projects,\n'
      '      keyOf: (row) => row.id,\n'
      '      striped: true,\n'
      '      maxHeight: 260,\n'
      '      rowActionsBuilder: (context, row) => AstryxDropdownMenu(\n'
      '        width: 180,\n'
      '        entries: <AstryxMenuEntry>[\n'
      '          AstryxMenuItem(label: \'Open \${row.name}\', onSelected: () {}),\n'
      '          const AstryxMenuDivider(),\n'
      '          AstryxMenuItem(label: \'Delete\', destructive: true, onSelected: () {}),\n'
      '        ],\n'
      '        triggerBuilder: (context, controller) => AstryxIconButton(\n'
      '          icon: AstryxIconName.moreHorizontal,\n'
      '          label: \'Actions for \${row.name}\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          size: AstryxButtonSize.sm,\n'
      '          onPressed: controller.toggle,\n'
      '        ),\n'
      '      ),\n'
      '      columns: <AstryxTableColumn<Project>>[\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'name\',\n'
      '          header: \'Project\',\n'
      '          cellBuilder: (context, row) => AstryxText(row.name),\n'
      '        ),\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'owner\',\n'
      '          header: \'Owner\',\n'
      '          headerTooltip: \'Who gets paged first\',\n'
      '          cellBuilder: (context, row) => AstryxText(row.owner),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/table_examples.dart
  'table_density':
      'class TableDensityExample extends StatefulWidget {\n'
      '  const TableDensityExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TableDensityExample> createState() => _TableDensityExampleState();\n'
      '}\n'
      '\n'
      'class _TableDensityExampleState extends State<TableDensityExample> {\n'
      '  AstryxTableDensity _density = AstryxTableDensity.balanced;\n'
      '  bool _striped = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing4,\n'
      '          wrap: true,\n'
      '          runGap: AstryxSpacingToken.spacing3,\n'
      '          children: <Widget>[\n'
      '            AstryxSelector<AstryxTableDensity>(\n'
      '              label: \'Density\',\n'
      '              value: _density,\n'
      '              width: 200,\n'
      '              onChanged: (value) =>\n'
      '                  setState(() => _density = value ?? _density),\n'
      '              options: <AstryxSelectorEntry<AstryxTableDensity>>[\n'
      '                for (final density in AstryxTableDensity.values)\n'
      '                  AstryxSelectorOption<AstryxTableDensity>(\n'
      '                    value: density,\n'
      '                    label: density.name,\n'
      '                  ),\n'
      '              ],\n'
      '            ),\n'
      '            AstryxSwitch(\n'
      '              label: \'Striped\',\n'
      '              value: _striped,\n'
      '              onChanged: (value) => setState(() => _striped = value),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxTable<Project>(\n'
      '          label: \'Projects\',\n'
      '          rows: projects,\n'
      '          keyOf: (row) => row.id,\n'
      '          density: _density,\n'
      '          striped: _striped,\n'
      '          columns: <AstryxTableColumn<Project>>[\n'
      '            AstryxTableColumn<Project>(\n'
      '              id: \'name\',\n'
      '              header: \'Project\',\n'
      '              cellBuilder: (context, row) => AstryxText(row.name),\n'
      '            ),\n'
      '            AstryxTableColumn<Project>(\n'
      '              id: \'owner\',\n'
      '              header: \'Owner\',\n'
      '              cellBuilder: (context, row) => AstryxText(row.owner),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/table_examples.dart
  'table_widths':
      'class TableWidthsExample extends StatelessWidget {\n'
      '  const TableWidthsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Three strategies, one row: flexible columns share what is left, fixed\n'
      '    // columns take theirs, and an intrinsic column is as wide as its widest\n'
      '    // cell — clamped, so one long value cannot push the rest off-screen.\n'
      '    return AstryxTable<Project>(\n'
      '      label: \'Column widths\',\n'
      '      rows: projects,\n'
      '      keyOf: (row) => row.id,\n'
      '      minWidth: 520,\n'
      '      columns: <AstryxTableColumn<Project>>[\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'name\',\n'
      '          header: \'flex(1)\',\n'
      '          cellBuilder: (context, row) => AstryxText(row.name),\n'
      '        ),\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'owner\',\n'
      '          header: \'flex(2)\',\n'
      '          width: const AstryxTableColumnWidth.flex(2),\n'
      '          cellBuilder: (context, row) => AstryxText(row.owner),\n'
      '        ),\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'health\',\n'
      '          header: \'intrinsic\',\n'
      '          width: const AstryxTableColumnWidth.intrinsic(min: 80, max: 160),\n'
      '          cellBuilder: (context, row) =>\n'
      '              AstryxBadge(row.health, variant: variantFor(row.health)),\n'
      '        ),\n'
      '        AstryxTableColumn<Project>(\n'
      '          id: \'requests\',\n'
      '          header: \'fixed(110)\',\n'
      '          width: const AstryxTableColumnWidth.fixed(110),\n'
      '          alignment: AstryxTableAlignment.end,\n'
      '          cellBuilder: (context, row) =>\n'
      '              AstryxText(\'\${row.requests}\', tabularNumbers: true),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
