      'class TextTruncationExample extends StatelessWidget {\n'
      '  const TextTruncationExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `truncateTooltip` shows the full string on hover — but only when the\n'
      '    // text is genuinely cut off, so a tooltip never repeats what is already\n'
      '    // legible. A screen reader always gets the whole string.\n'
      '    return const SizedBox(\n'
      '      width: 240,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxText(\n'
      '            \'analytics-pipeline-eu-west-1.internal.example.com\',\n'
      '            maxLines: 1,\n'
      '            truncateTooltip: true,\n'
      '          ),\n'
      '          AstryxText(\n'
      '            \'A description long enough to need two lines and then some more, \'\n'
      '            \'which is where the ellipsis lands.\',\n'
      '            maxLines: 2,\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
