  // examples/text_examples.dart
  'text_semantics':
      'class TextSemanticsExample extends StatelessWidget {\n'
      '  const TextSemanticsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // What is read aloud need not be what is painted. `\$1.2M` is a glyph\n'
      '    // salad to a screen reader; the label says it in words.\n'
      '    return const AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing1,\n'
      '      children: <Widget>[\n'
      '        AstryxText(\n'
      '          r\'\$1.2M\',\n'
      '          type: AstryxTextType.display3,\n'
      '          semanticsLabel: \'1.2 million dollars\',\n'
      '        ),\n'
      '        AstryxText(\n'
      '          \'Annual recurring revenue\',\n'
      '          type: AstryxTextType.supporting,\n'
