  // examples/theming_examples.dart
  'theming_themes':
      'class ThemingThemesExample extends StatelessWidget {\n'
      '  const ThemingThemesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Every theme is a value. Nesting a provider re-themes a subtree, which is\n'
      '    // how a preview like this one can show all seven at once.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 150,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final theme in <(String, AstryxDefinedTheme)>[\n'
      '          (\'neutral\', neutralTheme),\n'
      '          (\'matcha\', matchaTheme),\n'
      '          (\'stone\', stoneTheme),\n'
      '          (\'gothic\', gothicTheme),\n'
      '          (\'chocolate\', chocolateTheme),\n'
      '          (\'y2k\', y2kTheme),\n'
      '          (\'butter\', butterTheme),\n'
      '          (\'acme (custom)\', acmeTheme),\n'
      '        ])\n'
      '          AstryxThemeProvider(\n'
      '            theme: theme.\$2,\n'
      '            child: AstryxCard(\n'
      '              padding: AstryxSpacingToken.spacing3,\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(theme.\$1, type: AstryxTextType.label),\n'
      '                  AstryxButton(\n'
      '                    label: \'Primary\',\n'
      '                    variant: AstryxButtonVariant.primary,\n'
      '                    size: AstryxButtonSize.sm,\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                  const AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing1,\n'
      '                    wrap: true,\n'
      '                    runGap: AstryxSpacingToken.spacing1,\n'
      '                    children: <Widget>[\n'
      '                      AstryxBadge(\'A\', variant: AstryxBadgeVariant.info),\n'
      '                      AstryxBadge(\'B\', variant: AstryxBadgeVariant.success),\n'
      '                      AstryxBadge(\'C\', variant: AstryxBadgeVariant.error),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/theming_examples.dart
  'theming_modes':
      'class ThemingModesExample extends StatelessWidget {\n'
      '  const ThemingModesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `mode` defaults to `system`, which tracks the platform\'s own preference\n'
      '    // through `MediaQuery` — no rebuild of your own required.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 200,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final mode in <AstryxColorMode>[\n'
      '          AstryxColorMode.light,\n'
      '          AstryxColorMode.dark,\n'
      '        ])\n'
      '          AstryxThemeProvider(\n'
      '            mode: mode,\n'
      '            child: Builder(\n'
      '              builder: (context) => ColoredBox(\n'
      '                color: AstryxTheme.of(\n'
      '                  context,\n'
      '                ).color(AstryxColorToken.backgroundBody),\n'
      '                child: Padding(\n'
      '                  padding: const EdgeInsets.all(16),\n'
      '                  child: AstryxVStack(\n'
      '                    gap: AstryxSpacingToken.spacing2,\n'
      '                    align: AstryxStackAlign.stretch,\n'
      '                    children: <Widget>[\n'
      '                      AstryxText(mode.name, type: AstryxTextType.label),\n'
      '                      const AstryxText(\n'
      '                        \'Body copy on the page background.\',\n'
      '                        color: AstryxTextColor.secondary,\n'
      '                      ),\n'
      '                      AstryxButton(\n'
      '                        label: \'Primary\',\n'
      '                        variant: AstryxButtonVariant.primary,\n'
      '                        size: AstryxButtonSize.sm,\n'
      '                        onPressed: () {},\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/theming_examples.dart
  'theming_tokens':
      'class ThemingTokensExample extends StatelessWidget {\n'
      '  const ThemingTokensExample({super.key});\n'
      '\n'
      '  /// The tokens a page reaches for most often. There are 100-odd in total.\n'
      '  static const List<AstryxColorToken> _tokens = <AstryxColorToken>[\n'
      '    AstryxColorToken.accent,\n'
      '    AstryxColorToken.accentMuted,\n'
      '    AstryxColorToken.backgroundBody,\n'
      '    AstryxColorToken.backgroundSurface,\n'
      '    AstryxColorToken.backgroundCard,\n'
      '    AstryxColorToken.backgroundMuted,\n'
      '    AstryxColorToken.border,\n'
      '    AstryxColorToken.borderEmphasized,\n'
      '    AstryxColorToken.success,\n'
      '    AstryxColorToken.warning,\n'
      '    AstryxColorToken.error,\n'
      '    AstryxColorToken.backgroundInverted,\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxGrid(\n'
      '      minWidth: 180,\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        for (final token in _tokens)\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              DecoratedBox(\n'
      '                decoration: BoxDecoration(\n'
      '                  color: theme.color(token),\n'
      '                  borderRadius: theme.borderRadius(AstryxRadiusToken.inner),\n'
      '                  border: Border.all(\n'
      '                    color: theme.color(AstryxColorToken.border),\n'
      '                  ),\n'
      '                ),\n'
      '                child: const SizedBox(width: 24, height: 24),\n'
      '              ),\n'
      '              Flexible(\n'
      '                child: AstryxText(\n'
      '                  token.name,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
