  // examples/theming_examples.dart
  'theming_density':
      'class ThemingDensityExample extends StatelessWidget {\n'
      '  const ThemingDensityExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Touch density raises every tap target to 48px and suppresses hover-only\n'
      '    // affordances. The control\'s painted height does not change — the region\n'
      '    // that responds to a finger does.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 220,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final density in AstryxDensity.values)\n'
      '          AstryxThemeProvider(\n'
      '            density: density,\n'
      '            child: AstryxCard(\n'
      '              padding: AstryxSpacingToken.spacing3,\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(\n'
      '                    \'\${density.name} · min target \'\n'
      '                    \'\${density.minimumTapTarget.toInt()}px\',\n'
      '                    type: AstryxTextType.label,\n'
      '                  ),\n'
      '                  AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing2,\n'
      '                    children: <Widget>[\n'
      '                      AstryxButton(label: \'Save\', onPressed: () {}),\n'
      '                      AstryxIconButton(\n'
      '                        icon: AstryxIconName.copy,\n'
      '                        label: \'Copy\',\n'
      '                        onPressed: () {},\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                  AstryxCheckbox(\n'
      '                    label: \'Also a target\',\n'
      '                    value: true,\n'
      '                    onChanged: (_) {},\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
