  // examples/toast_examples.dart
  'toast_action':
      'class ToastActionExample extends StatefulWidget {\n'
      '  const ToastActionExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ToastActionExample> createState() => _ToastActionExampleState();\n'
      '}\n'
      '\n'
      'class _ToastActionExampleState extends State<ToastActionExample> {\n'
      '  bool _deleted = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(\n'
      '          label: \'Delete row\',\n'
      '          onPressed: () {\n'
      '            setState(() => _deleted = true);\n'
      '            AstryxToastScope.of(context).show(\n'
      '              AstryxToast(\n'
      '                message: \'Row deleted\',\n'
      '                action: AstryxButton(\n'
      '                  label: \'Undo\',\n'
      '                  variant: AstryxButtonVariant.ghost,\n'
      '                  size: AstryxButtonSize.sm,\n'
      '                  onPressed: () => setState(() => _deleted = false),\n'
      '                ),\n'
      '              ),\n'
      '            );\n'
      '          },\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _deleted ? \'Row is deleted\' : \'Row is present\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toast_examples.dart
  'toast_duration':
      'class ToastDurationExample extends StatelessWidget {\n'
      '  const ToastDurationExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      wrap: true,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(\n'
      '          label: \'Two seconds\',\n'
      '          onPressed: () => AstryxToastScope.of(context).show(\n'
      '            const AstryxToast(\n'
      '              message: \'Gone in two\',\n'
      '              duration: Duration(seconds: 2),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        // `Duration.zero` pins it until the user dismisses it. Hover or focus\n'
      '        // also pauses the timeout — a toast must not vanish while someone is\n'
      '        // reaching for its Undo.\n'
      '        AstryxButton(\n'
      '          label: \'Until dismissed\',\n'
      '          onPressed: () => AstryxToastScope.of(context).show(\n'
      '            const AstryxToast(\n'
      '              message: \'Pinned until dismissed\',\n'
      '              duration: Duration.zero,\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: \'Not dismissible\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          onPressed: () => AstryxToastScope.of(context).show(\n'
      '            const AstryxToast(\n'
      '              message: \'No dismiss button, five seconds\',\n'
      '              dismissible: false,\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toast_examples.dart
  'toast_queue':
      'class ToastQueueExample extends StatelessWidget {\n'
      '  const ToastQueueExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        // Beyond `maxVisible` (five by default) the rest queue and take their\n'
      '        // turn, rather than burying the screen.\n'
      '        AstryxButton(\n'
      '          label: \'Show eight\',\n'
      '          onPressed: () {\n'
      '            final toasts = AstryxToastScope.of(context);\n'
      '            for (var i = 1; i <= 8; i++) {\n'
      '              toasts.show(AstryxToast(message: \'Notification \$i\'));\n'
      '            }\n'
      '          },\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: \'Clear\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          onPressed: () => AstryxToastScope.of(context).clear(),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
