  // examples/tooltip_examples.dart
  'tooltip_timing':
      'class TooltipTimingExample extends StatelessWidget {\n'
      '  const TooltipTimingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The wait is what stops a tooltip firing at everything the mouse crosses\n'
      '    // on its way somewhere else.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      wrap: true,\n'
      '      children: <Widget>[\n'
      '        AstryxTooltip(\n'
      '          message: \'Appears at once\',\n'
      '          waitDuration: Duration.zero,\n'
      '          child: AstryxButton(label: \'No wait\', onPressed: () {}),\n'
      '        ),\n'
      '        AstryxTooltip(\n'
      '          message: \'Appears after 200ms — the default\',\n'
      '          child: AstryxButton(label: \'Default\', onPressed: () {}),\n'
      '        ),\n'
      '        AstryxTooltip(\n'
      '          message: \'Appears after a second\',\n'
      '          waitDuration: const Duration(seconds: 1),\n'
      '          exitDuration: const Duration(milliseconds: 400),\n'
      '          child: AstryxButton(label: \'Patient\', onPressed: () {}),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/tooltip_examples.dart
  'tooltip_semantics':
      'class TooltipSemanticsExample extends StatelessWidget {\n'
      '  const TooltipSemanticsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      children: <Widget>[\n'
      '        // The tooltip repeats the button\'s own name, so it is left out of the\n'
      '        // semantics tree. Hearing "Archive, Archive" is worse than silence.\n'
      '        AstryxTooltip(\n'
      '          message: \'Archive\',\n'
      '          excludeFromSemantics: true,\n'
      '          child: AstryxIconButton(\n'
      '            icon: AstryxIconName.check,\n'
      '            label: \'Archive\',\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ),\n'
      '        // This one says something the name does not, so it stays announced.\n'
      '        AstryxTooltip(\n'
      '          message: \'Archived items are kept for 30 days\',\n'
      '          child: AstryxIconButton(\n'
      '            icon: AstryxIconName.info,\n'
      '            label: \'About archiving\',\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
